package main

import "fmt"

func classify(day string) string {
	switch day {
	case "Sat", "Sun": // multiple values, one case
		return "weekend"
	default:
		return "weekday"
	}
}

func main() {
	fmt.Println(classify("Sat"), classify("Mon"))
}
// Output: weekend weekday

package main

import "fmt"

func describe(x interface{}) string {
	switch v := x.(type) { // branch on dynamic type
	case int:
		return fmt.Sprintf("int:%d", v)
	case string:
		return fmt.Sprintf("string:%s", v)
	default:
		return "unknown"
	}
}

func main() {
	fmt.Println(describe(7), describe("hi"))
}
// Output: int:7 string:hi

