package main

import "fmt"

func main() {
	// 1) three-component (classic counter)
	for i := 0; i < 3; i++ {
		fmt.Print(i, " ")
	}
	fmt.Println()

	// 2) condition-only (while-style)
	n := 3
	for n > 0 {
		fmt.Print(n, " ")
		n--
	}
	fmt.Println()

	// 3) bare infinite loop with break
	count := 0
	for {
		if count == 2 {
			break
		}
		fmt.Print("tick ")
		count++
	}
	fmt.Println()

	// 4) for-range over a slice
	for i, v := range []string{"a", "b"} {
		fmt.Printf("%d=%s ", i, v)
	}
	fmt.Println()
}

