		{15, []string{"1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz", "11", "Fizz", "13", "14", "FizzBuzz"}},
	}
	for _, c := range cases {
		if got := Solve(c.n); !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%d)=%v want %v", c.n, got, c.want)
		}
	}
}

