import "unicode"

func CountVowels(s string) int {
	count := 0
	for _, r := range s { // range yields runes, not bytes
		switch unicode.ToLower(r) { // normalize case once
		case 'a', 'e', 'i', 'o', 'u': // one case, multiple values
			count++
		}
	}
	return count
}
